class HomeShell extends StatefulWidget { const HomeShell({super.key}); @override State<HomeShell> createState() => _HomeShellState(); }
class _HomeShellState extends State<HomeShell> {
  final store = StorageService(); List<Habit> habits=[]; List<Map<String,dynamic>> todos=[]; Map<String,int> moods={}; Map<String,int> timers={}; DateTime selected=DateTime.now(); String? pin; String userName=''; int tab=0; bool loading=true,locked=false;
  @override void initState(){super.initState();load();}
  Future<void> load() async { habits=await store.loadHabits(); todos=await store.loadTodos(); moods=await store.loadMoods(); timers=await store.loadTimerSeconds(); pin=await store.loadPin(); userName=await store.loadName(); locked=pin!=null&&pin!.isNotEmpty; if(mounted)setState(()=>loading=false); }
  Future<void> saveHabits()=>store.saveHabits(habits);
  Future<void> saveName(String value) async { final name=value.trim(); await store.saveName(name); if(!mounted)return; WidgetsBinding.instance.addPostFrameCallback((_){if(mounted)setState(()=>userName=name);}); }
  Future<void> addHabit() async { final f=await showModalBottomSheet<HabitForm>(context:context,isScrollControlled:true,builder:(_)=>const HabitEditor()); if(f==null||f.name.trim().isEmpty)return; habits.add(f.makeHabit());setState((){});await saveHabits(); }
  Future<void> editHabit(Habit h) async { final f=await showModalBottomSheet<HabitForm>(context:context,isScrollControlled:true,builder:(_)=>HabitEditor(habit:h)); if(f==null)return; if(f.delete)habits.removeWhere((x)=>x.id==h.id);else{h.name=f.name;h.category=f.category;h.goal=f.goal;h.unit=f.unit;h.frequency=f.frequency;h.weekdays=f.weekdays;h.tags=f.tags;h.notes=f.notes;h.pinned=f.pinned;h.active=f.active;}setState((){});await saveHabits(); }
  Future<void> toggleHabit(Habit h,DateTime d) async {h.setDone(d,!h.isDone(d));setState((){});await saveHabits();}
  Future<void> openHabit(Habit h) async {await Navigator.push(context,MaterialPageRoute(builder:(_)=>HabitDetail(habit:h,onSave:saveHabits)));if(mounted)setState((){});}
  Future<void> addTodo() async {final f=await showDialog<TodoForm>(context:context,builder:(_)=>const TodoEditor());if(f==null||f.title.trim().isEmpty)return;todos.add({'id':DateTime.now().microsecondsSinceEpoch.toString(),'title':f.title.trim(),'category':f.category,'priority':f.priority,'done':false});setState((){});await store.saveTodos(todos);}
  Future<void> editTodo(int i) async {final f=await showDialog<TodoForm>(context:context,builder:(_)=>TodoEditor(existing:todos[i]));if(f==null)return;todos[i]['title']=f.title.trim();todos[i]['category']=f.category;todos[i]['priority']=f.priority;setState((){});await store.saveTodos(todos);}
  Future<void> toggleTodo(int i) async {todos[i]['done']=todos[i]['done']!=true;setState((){});await store.saveTodos(todos);}
  Future<void> deleteTodo(int i) async {todos.removeAt(i);setState((){});await store.saveTodos(todos);}
  Future<void> setMood(int v) async {moods[Habit.key(selected)]=v;setState((){});await store.saveMoods(moods);}
  Future<void> openTimer() async {final k=Habit.key(selected);final v=await Navigator.push<int>(context,MaterialPageRoute(builder:(_)=>FocusTimer(initial:timers[k]??0)));if(v==null)return;timers[k]=v;setState((){});await store.saveTimerSeconds(timers);}
  Future<void> setPin() async {final v=await showDialog<String>(context:context,builder:(_)=>const PinDialog());if(v==null)return;await store.savePin(v);setState((){pin=v.isEmpty?null:v;locked=false;});}
  Future<void> unlock() async {final ok=await showDialog<bool>(context:context,barrierDismissible:false,builder:(_)=>LockDialog(pin:pin!));if(ok==true&&mounted)setState(()=>locked=false);}
  Future<void> editName() async {final v=await showDialog<String>(context:context,builder:(_)=>NameDialog(initialName:userName));if(v==null)return;await saveName(v);}
  @override Widget build(BuildContext context){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(locked)return LockScreen(onUnlock:unlock);final greeting=userName.isEmpty?'Good day 👋':'Good day, $userName 👋';final pages=<Widget>[Dashboard(habits:habits,date:selected,moods:moods,greeting:greeting,onToggle:toggleHabit,onEdit:editHabit,onOpen:openHabit,onAdd:addHabit,onMood:setMood,onTimer:openTimer),Daily(habits:habits,date:selected,onDate:(d)=>setState(()=>selected=d),onToggle:toggleHabit,onEdit:editHabit,onOpen:openHabit,onAdd:addHabit),Stats(habits:habits),TodoPage(todos:todos,onAdd:addTodo,onEdit:editTodo,onToggle:toggleTodo,onDelete:deleteTodo),Profile(habits:habits,userName:userName,hasPin:pin!=null,onTimer:openTimer,onPin:setPin,onName:editName)];return Scaffold(body:SafeArea(child:IndexedStack(index:tab,children:pages)),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home_rounded),label:'Home'),NavigationDestination(icon:Icon(Icons.check_circle_outline_rounded),selectedIcon:Icon(Icons.check_circle_rounded),label:'Habits'),NavigationDestination(icon:Icon(Icons.insights_outlined),selectedIcon:Icon(Icons.insights_rounded),label:'Stats'),NavigationDestination(icon:Icon(Icons.checklist_rounded),selectedIcon:Icon(Icons.checklist_rounded),label:'To-Do'),NavigationDestination(icon:Icon(Icons.person_outline_rounded),selectedIcon:Icon(Icons.person_rounded),label:'Profile')]));}
}

