class _NameDialogState extends State<NameDialog>{late final TextEditingController controller;@override void initState(){super.initState();controller=TextEditingController(text:widget.initialName);}@override void dispose(){controller.dispose();super.dispose();}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('Your name',style:TextStyle(fontWeight:FontWeight.w800)),content:TextField(controller:controller,autofocus:true,textCapitalization:TextCapitalization.words,decoration:const InputDecoration(labelText:'Name',hintText:'Enter your name')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,controller.text.trim()),child:const Text('Save'))]);}
class LockDialog extends StatefulWidget{final String pin;const LockDialog({super.key,required this.pin});@override State<LockDialog>createState()=>_LockDialogState();}
class _LockDialogState extends State<LockDialog>{final controller=TextEditingController();String error='';@override void dispose(){controller.dispose();super.dispose();}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('Unlock HabitUs',style:TextStyle(fontWeight:FontWeight.w800)),content:TextField(controller:controller,obscureText:true,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:'PIN',errorText:error.isEmpty?null:error)),actions:[FilledButton(onPressed:(){if(controller.text==widget.pin)Navigator.pop(context,true);else setState(()=>error='Incorrect PIN');},child:const Text('Unlock'))]);}
class LockScreen extends StatelessWidget{final VoidCallback onUnlock;const LockScreen({super.key,required this.onUnlock});@override Widget build(BuildContext c)=>Scaffold(body:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Container(width:84,height:84,decoration:BoxDecoration(color:AppColors.soft,borderRadius:BorderRadius.circular(26)),child:const Icon(Icons.lock_rounded,size:38,color:AppColors.blue)),const SizedBox(height:18),const Text('HabitUs is locked',style:TextStyle(fontSize:22,fontWeight:FontWeight.w800)),const SizedBox(height:20),FilledButton(onPressed:onUnlock,child:const Text('Unlock'))]));}
